import{_ as i,o as l,c as e,ag as a}from"./chunks/framework.IxO3mcwW.js";const o="/getbiji-docs/images/kb-live-01.png",s="/getbiji-docs/images/kb-live-02.png",r="/getbiji-docs/images/kb-live-03.png",p="/getbiji-docs/images/kb-live-04.png",h=JSON.parse('{"title":"帮你听直播","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge-base/livestream.md","filePath":"knowledge-base/livestream.md","lastUpdated":1773215704000}'),n={name:"knowledge-base/livestream.md"};function d(c,t,u,g,m,b){return l(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="帮你听直播" tabindex="-1">帮你听直播 <a class="header-anchor" href="#帮你听直播" aria-label="Permalink to &quot;帮你听直播&quot;">​</a></h1><blockquote><p>🎧 Get 笔记帮你听直播，知识不再错过</p></blockquote><p>只需将直播链接或二维码上传，AI 就能替你全程聆听并记录，生成清晰的内容总结和章节纪要。</p><p>错过直播也无需担忧，你可以随时回看直播回放或查看全文稿，快速掌握核心内容，让每一场高质量讲座都为你所用。</p><h2 id="app端使用说明" tabindex="-1">APP端使用说明 <a class="header-anchor" href="#app端使用说明" aria-label="Permalink to &quot;APP端使用说明&quot;">​</a></h2><ol><li><p>创建一个个人知识库，在知识库内，点击&quot;添加内容&quot;按钮，并选择&quot;订阅直播/博主&quot;</p></li><li><p>可以支持订阅 <strong>得到App直播</strong> 和 <strong>视频号直播</strong></p></li><li><p><strong>得到App直播</strong>：可以订阅未开始、进行中和回放的得到 APP 直播，直接粘贴直播链接即可订阅</p></li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><ul><li>已下架的直播，不支持订阅</li><li>会员专享的直播，不支持订阅</li></ul></div><ol start="4"><li><p><strong>如何找到得到 APP 的直播链接？</strong></p><ul><li>打开得到 App，找到想要订阅的直播</li><li>点击直播页面右上角「分享」按钮</li><li>选择「复制链接」</li><li>将链接粘贴到 Get 笔记即可</li></ul></li><li><p>直播结束后，Get 笔记会帮你生成清晰的内容总结和章节纪要（这个过程 AI 需要 30-40 分钟的分析处理）</p></li></ol><h2 id="网页端使用说明" tabindex="-1">网页端使用说明 <a class="header-anchor" href="#网页端使用说明" aria-label="Permalink to &quot;网页端使用说明&quot;">​</a></h2><ol><li><p>进入你创建的知识库，点击&quot;添加&quot;按钮，选择&quot;订阅直播/博主&quot;</p></li><li><p>目前支持订阅 <strong>得到APP直播</strong></p></li><li><p>得到APP直播，可以订阅未开始、进行中和回放的得到APP直播，直接粘贴直播链接即可订阅</p></li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><ul><li>已下架的直播，不支持订阅</li><li>会员专享的直播，不支持订阅</li></ul></div><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+o+'" alt="添加直播" style="width:180px;border-radius:8px;"><img src="'+s+'" alt="粘贴链接" style="width:180px;border-radius:8px;"><img src="'+r+'" alt="订阅成功" style="width:180px;border-radius:8px;"><img src="'+p+'" alt="直播笔记" style="width:180px;border-radius:8px;"></div>',13)])])}const P=i(n,[["render",d]]);export{h as __pageData,P as default};
